  /// Retrieves the stroke attributes used in this @node.
  static final _gskStrokeNodeGetStroke =
      gsk4Lookup<
            ffi.NativeFunction<
              ffi.Pointer<ffi.Void> Function(ffi.Pointer<ffi.Void>)
